'use cache';
const productsCacheTag = 'products';

async function getProducts() {
  'use cache';
  cacheTag(productsCacheTag);
  const { getAllProducts } = await import('../lib/db');
  return getAllProducts();
}

async function invalidateProductsCache() {
  'use server';
  revalidateTag(productsCacheTag);
  return { success: true, message: 'Products cache invalidated' };
}

interface Product {
  id: number;
  name: string;
  price: number;
}

function ProductList({ products }: { products: Product[] }) {
  return (
    <div className="product-list">
      <h2>Products</h2>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

function CacheInvalidationForm() {
  return (
    <form action={invalidateProductsCache} className="invalidate-form">
      <button type="submit">Refresh Products Cache</button>
    </form>
  );
}

export default async function Page() {
  const products = await getProducts();

  return (
    <div className="container">
      <h1>Product Listing</h1>
      <CacheInvalidationForm />
      <ProductList products={products} />
    </div>
  );
}

